package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)

	line, _ := reader.ReadString('\n')
	_, _ = strconv.Atoi(strings.TrimSpace(line))

	str, _ := reader.ReadString('\n')
	str = strings.TrimSpace(str)

	maxCount := 0
	currentSet := make(map[rune]bool)

	for _, ch := range str {
		if ch >= 'a' && ch <= 'z' {
			currentSet[ch] = true
		} else {
			if len(currentSet) > maxCount {
				maxCount = len(currentSet)
			}
			currentSet = make(map[rune]bool)
		}
	}

	if len(currentSet) > maxCount {
		maxCount = len(currentSet)
	}

	fmt.Println(maxCount)
}

