import (
	"bufio"
	"fmt"
	"os"
	"unicode"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	scanner.Scan()
	var n int
	fmt.Sscan(scanner.Text(), &n)

	scanner.Scan()
	s := scanner.Text()

	max := 0
	for i := 0; i < len(s); i++ {
		if unicode.IsLower(rune(s[i])) {
			set := make(map[rune]struct{})
			for j := i; j < len(s); j++ {
				if unicode.IsLower(rune(s[j])) {
					set[rune(s[j])] = struct{}{}
				} else {
					break
				}
			}
			if len(set) > max {
				max = len(set)
			}
		}
	}

	fmt.Println(max)
}

